const LBL={live:'Live',saved:'Saved for later',lost:'Lost',doze:'Napping',off:'Off'};
const COL={live:'var(--live)',saved:'var(--saved)',lost:'var(--lost)',doze:'var(--doze)',off:'var(--muted)'};
let day='typ',sel=2;
function kind(s){return $('#dfix').checked&&s.fk?s.fk:s.k}
function led(l){if(l==='redblink')return `<span class="dot blink" style="background:${LED.red}"></span>Blinking red`;if(l==='off')return `<span class="dot" style="background:${LED.off}"></span>Dark`;return `<span class="dot" style="background:${LED[l]}"></span>${{blue:'Blue',red:'Red',green:'Green'}[l]}`}
function dayRender(){
  const d=DAYS[day],fix=$('#dfix').checked;
  $('#sc-typ').setAttribute('aria-pressed',day==='typ');$('#sc-new').setAttribute('aria-pressed',day==='neu');
  $('#tl').innerHTML=d.map((s,i)=>`<button type="button" class="blk ${kind(s)}" style="flex:${s.h}" aria-pressed="${i===sel}" data-i="${i}" aria-label="${s.t}: ${s.n}, ${LBL[kind(s)]}">${s.t}</button>`).join('');
  $$('#tl .blk').forEach(b=>b.onclick=()=>{sel=+b.dataset.i;dayRender()});
  const s=d[sel],k=kind(s),ch=fix&&s.fw;
  $('#dcard').innerHTML=`<div><span class="badge" style="font-family:var(--f-display);font-weight:600;color:${COL[k]}">${LBL[k]}</span><h3>${s.n}</h3><p style="margin:0">${ch?s.fw:s.w}</p></div><div><div class="mini"><b>The light</b>${led(s.led)}</div><div class="mini"><b>In the app</b>${ch&&s.fapp?s.fapp:s.app}</div></div>`;
  const tot={live:0,saved:0,lost:0,doze:0};d.forEach(x=>{const kk=kind(x);if(kk in tot)tot[kk]+=x.h});
  const f=h=>h%1?h.toFixed(1):h;
  $('#dtot').innerHTML=['live','saved','lost','doze'].map(k=>`<div><b style="color:${COL[k]}">${f(tot[k])} h</b><span>${LBL[k]}</span></div>`).join('');
}
$('#sc-typ').onclick=()=>{day='typ';sel=2;dayRender()};
$('#sc-new').onclick=()=>{day='neu';sel=0;dayRender()};
$('#dfix').onchange=dayRender;
dayRender();

